add("ar","B2","Toplum","عادل","adil","sıfat","نحتاج إلى نظام عادل.","Adil bir sisteme ihtiyacımız var.");
add("ar","B2","Toplum","ظالم","adaletsiz / zalim","sıfat","رفض الناس النظام الظالم.","İnsanlar adaletsiz sistemi reddetti.");
add("ar","B2","Toplum","شعبي","halkla ilgili / popüler","sıfat","حظي القرار بدعم شعبي.","Karar halk desteği aldı.");
add("ar","B2","Toplum","إنساني","insani","sıfat","تحتاج المنطقة إلى مساعدات إنسانية.","Bölgenin insani yardıma ihtiyacı var.");
add("ar","B2","Toplum","سلمي","barışçıl","sıfat","نظم المواطنون احتجاجا سلميا.","Vatandaşlar barışçıl bir protesto düzenledi.");
add("ar","B2","Toplum","قومي","milli / ulusal","sıfat","يحتفل الناس بالعيد القومي.","İnsanlar ulusal bayramı kutluyor.");
add("ar","B2","Toplum","المشاركة السياسية","siyasi katılım","ifade","تعد المشاركة السياسية مهمة في الديمقراطية.","Siyasi katılım demokraside önemlidir.");
add("ar","B2","Toplum","اتخاذ قرار سياسي","siyasi karar almak","ifade","يجب دراسة الوضع قبل اتخاذ قرار سياسي.","Siyasi karar almadan önce durum incelenmelidir.");
add("ar","B2","Toplum","احترام حقوق الإنسان","insan haklarına saygı göstermek","ifade","يجب على الجميع احترام حقوق الإنسان.","Herkes insan haklarına saygı göstermelidir.");
add("ar","B2","Toplum","خرق القانون","yasayı çiğnemek","ifade","يعاقب القانون من يخرق القانون.","Yasayı çiğneyen kişi kanun tarafından cezalandırılır.");
add("ar","B2","Toplum","رفع قضية","dava açmak","ifade","قرر رفع قضية ضد الشركة.","Şirkete karşı dava açmaya karar verdi.");
add("ar","B2","Toplum","الوصول إلى العدالة","adalete erişmek","ifade","يجب أن يتمكن الجميع من الوصول إلى العدالة.","Herkes adalete erişebilmelidir.");
add("ar","B2","Toplum","مكافحة التمييز","ayrımcılıkla mücadele etmek","ifade","تهدف الحملة إلى مكافحة التمييز.","Kampanya ayrımcılıkla mücadele etmeyi amaçlıyor.");
add("ar","B2","Toplum","دعم الفئات الضعيفة","savunmasız kesimleri desteklemek","ifade","تقدم الدولة المساعدة لدعم الفئات الضعيفة.","Devlet savunmasız kesimleri desteklemek için yardım sağlıyor.");
add("ar","B2","Toplum","تحسين الخدمات العامة","kamu hizmetlerini iyileştirmek","ifade","تعمل البلدية على تحسين الخدمات العامة.","Belediye kamu hizmetlerini iyileştirmek için çalışıyor.");
add("ar","B2","Toplum","تحقيق المساواة","eşitliği sağlamak","ifade","تسعى المنظمة إلى تحقيق المساواة.","Kuruluş eşitliği sağlamaya çalışıyor.");
add("ar","B2","Toplum","الحفاظ على السلام","barışı korumak","ifade","يجب على الجميع العمل من أجل الحفاظ على السلام.","Herkes barışı korumak için çalışmalıdır.");
add("ar","B2","Toplum","تعزيز التعاون الدولي","uluslararası işbirliğini güçlendirmek","ifade","يساعد الحوار على تعزيز التعاون الدولي.","Diyalog uluslararası işbirliğini güçlendirmeye yardımcı olur.");
add("ar","B2","Ekonomi","معدل التضخم","enflasyon oranı","isim","تحاول الحكومة خفض معدل التضخم.","Hükümet enflasyon oranını düşürmeye çalışıyor.");
add("ar","B2","Ekonomi","معدل البطالة","işsizlik oranı","isim","انخفض معدل البطالة قليلا.","İşsizlik oranı biraz düştü.");
add("ar","B2","Ekonomi","دخل الفرد","kişi başına gelir","isim","يزداد دخل الفرد مع النمو الاقتصادي.","Ekonomik büyümeyle kişi başına gelir artıyor.");
add("ar","B2","Ekonomi","تكلفة المعيشة","yaşam maliyeti","isim","ارتفعت تكلفة المعيشة في المدن الكبرى.","Büyük şehirlerde yaşam maliyeti arttı.");
add("ar","B2","Ekonomi","قوة شرائية","satın alma gücü","isim","أدى التضخم إلى انخفاض القوة الشرائية.","Enflasyon satın alma gücünün düşmesine neden oldu.");
add("ar","B2","Ekonomi","إيرادات","gelirler","isim","زادت إيرادات الشركة هذا العام.","Şirketin gelirleri bu yıl arttı.");
add("ar","B2","Ekonomi","نفقات","harcamalar / giderler","isim","تحاول الحكومة خفض النفقات.","Hükümet harcamaları azaltmaya çalışıyor.");
add("ar","B2","Ekonomi","رأس مال","sermaye","isim","تحتاج الشركة إلى رأس مال إضافي.","Şirketin ek sermayeye ihtiyacı var.");
add("ar","B2","Ekonomi","سعر الفائدة","faiz oranı","isim","تؤثر أسعار الفائدة في الاستثمار.","Faiz oranları yatırımları etkiler.");
add("ar","B2","Ekonomi","بورصة","borsa","isim","تراجعت البورصة بعد الأخبار السلبية.","Olumsuz haberlerden sonra borsa düştü.");
add("ar","B2","Ekonomi","سهم","hisse senedi","isim","اشترى أسهما في شركة تكنولوجية.","Bir teknoloji şirketinin hisselerini satın aldı.");
add("ar","B2","İş ve Kariyer","قطاع","sektör","isim","يعمل في قطاع التكنولوجيا.","Teknoloji sektöründe çalışıyor.");
add("ar","B2","İş ve Kariyer","قطاع خاص","özel sektör","isim","يعمل في القطاع الخاص.","Özel sektörde çalışıyor.");
add("ar","B2","İş ve Kariyer","قطاع عام","kamu sektörü","isim","يعمل في القطاع العام.","Kamu sektöründe çalışıyor.");
add("ar","B2","İş ve Kariyer","زيادة في الراتب","maaş zammı","isim","حصل على زيادة في الراتب.","Maaş zammı aldı.");
add("ar","B2","İş ve Kariyer","فرصة مهنية","kariyer fırsatı","isim","توفر الشركة فرصا مهنية للموظفين.","Şirket çalışanlara kariyer fırsatları sunuyor.");
add("ar","B2","İş ve Kariyer","التوظيف","işe alım","isim","بدأت الشركة عملية التوظيف.","Şirket işe alım sürecini başlattı.");
add("ar","B2","İş ve Kariyer","موظف جديد","yeni çalışan","isim","انضم موظف جديد إلى الفريق.","Ekibe yeni bir çalışan katıldı.");
add("ar","B2","İş ve Kariyer","قيادة","liderlik","isim","تحتاج الإدارة إلى مهارات القيادة.","Yönetimin liderlik becerilerine ihtiyacı var.");
add("ar","B2","İş ve Kariyer","إنجاز","başarı / kazanım","isim","حقق إنجازا مهما في عمله.","İşinde önemli bir başarı elde etti.");

add("ar","B2","Ekonomi","يتراجع","gerilemek","fiil","تراجع السوق بعد الأزمة.","Krizden sonra piyasa geriledi.");
add("ar","B2","Ekonomi","يدخر","tasarruf etmek","fiil","يدخر جزءا من راتبه.","Maaşının bir kısmını biriktiriyor.");
add("ar","B2","Ekonomi","يستورد","ithal etmek","fiil","تستورد الدولة النفط.","Ülke petrol ithal ediyor.");
add("ar","B2","Ekonomi","يتاجر","ticaret yapmak","fiil","تتاجر الشركة مع دول مختلفة.","Şirket farklı ülkelerle ticaret yapıyor.");
add("ar","B2","Ekonomi","ينافس","rekabet etmek","fiil","تنافس الشركات في السوق.","Şirketler piyasada rekabet ediyor.");
add("ar","B2","İş ve Kariyer","تجاري","ticari","sıfat","وقعت الشركة اتفاقا تجاريا.","Şirket ticari bir anlaşma imzaladı.");
add("ar","B2","İş ve Kariyer","إداري","idari","sıfat","لديه خبرة في المجال الإداري.","İdari alanda deneyime sahip.");
add("ar","B2","İş ve Kariyer","تنافسي","rekabetçi","sıfat","يعمل في سوق تنافسي.","Rekabetçi bir piyasada çalışıyor.");
add("ar","B2","İş ve Kariyer","مربح","kârlı","sıfat","يبحث المستثمر عن مشروع مربح.","Yatırımcı kârlı bir proje arıyor.");
add("ar","B2","İş ve Kariyer","خاسر","zarar eden","sıfat","أغلقت الشركة المشروع الخاسر.","Şirket zarar eden projeyi kapattı.");
add("ar","B2","İş ve Kariyer","إنتاجي","üretken","sıfat","كان يوما إنتاجيا للغاية.","Oldukça üretken bir gündü.");
add("ar","B2","İş ve Kariyer","بدء مشروع تجاري","iş kurmak","ifade","يخطط لبدء مشروع تجاري جديد.","Yeni bir iş kurmayı planlıyor.");
add("ar","B2","İş ve Kariyer","تأسيس شركة","şirket kurmak","ifade","قرر تأسيس شركة في مجال التكنولوجيا.","Teknoloji alanında bir şirket kurmaya karar verdi.");
add("ar","B2","İş ve Kariyer","تحقيق الربح","kâr elde etmek","ifade","تهدف الشركة إلى تحقيق الربح.","Şirket kâr elde etmeyi amaçlıyor.");
add("ar","B2","İş ve Kariyer","تحمل الخسائر","zararları üstlenmek","ifade","يجب على المستثمر تحمل الخسائر المحتملة.","Yatırımcı olası zararları üstlenmelidir.");
add("ar","B2","İş ve Kariyer","اتخاذ قرار مالي","finansal karar vermek","ifade","يجب التفكير جيدا قبل اتخاذ قرار مالي.","Finansal karar vermeden önce iyi düşünmek gerekir.");
add("ar","B2","İş ve Kariyer","زيادة الإنتاجية","verimliliği artırmak","ifade","تساعد التكنولوجيا على زيادة الإنتاجية.","Teknoloji verimliliği artırmaya yardımcı olur.");
add("ar","B2","İş ve Kariyer","خفض التكاليف","maliyetleri düşürmek","ifade","تحاول الشركة خفض التكاليف.","Şirket maliyetleri düşürmeye çalışıyor.");
add("ar","B2","İş ve Kariyer","دخول السوق","pazara girmek","ifade","تخطط الشركة لدخول السوق الأوروبي.","Şirket Avrupa pazarına girmeyi planlıyor.");
add("ar","B2","İş ve Kariyer","المنافسة في السوق","piyasada rekabet etmek","ifade","يصعب على الشركات الصغيرة المنافسة في السوق.","Küçük şirketlerin piyasada rekabet etmesi zor.");
add("ar","B2","İş ve Kariyer","توسيع الأعمال","işi genişletmek","ifade","تريد الشركة توسيع أعمالها.","Şirket işini genişletmek istiyor.");
add("ar","B2","İş ve Kariyer","تطوير المهارات المهنية","mesleki becerileri geliştirmek","ifade","يساعد التدريب على تطوير المهارات المهنية.","Eğitim mesleki becerileri geliştirmeye yardımcı olur.");
add("ar","B2","İş ve Kariyer","الحصول على ترقية","terfi almak","ifade","يأمل في الحصول على ترقية قريبا.","Yakında terfi almayı umuyor.");
add("ar","B2","İş ve Kariyer","التقدم لوظيفة","bir işe başvurmak","ifade","قدم طلبا للتقدم لوظيفة جديدة.","Yeni bir işe başvuruda bulundu.");
add("ar","B2","İş ve Kariyer","اجتياز مقابلة العمل","iş görüşmesini geçmek","ifade","نجح في اجتياز مقابلة العمل.","İş görüşmesini başarıyla geçti.");
add("ar","B2","İş ve Kariyer","بناء مستقبل مهني","kariyer inşa etmek","ifade","يسعى إلى بناء مستقبل مهني ناجح.","Başarılı bir kariyer inşa etmeye çalışıyor.");
add("ar","B2","Çevre","تلوث التربة","toprak kirliliği","isim","يسبب التلوث الصناعي تلوث التربة.","Endüstriyel kirlilik toprak kirliliğine neden olur.");
add("ar","B2","Çevre","نفايات بلاستيكية","plastik atıklar","isim","تضر النفايات البلاستيكية بالبيئة.","Plastik atıklar çevreye zarar verir.");
add("ar","B2","Çevre","إعادة الاستخدام","yeniden kullanım","isim","تقلل إعادة الاستخدام من استهلاك الموارد.","Yeniden kullanım kaynak tüketimini azaltır.");
